(function(){
  var f=document.querySelector("select[name=groups],input[name=groups]");
  if(!f) return "NO_FIELD";
  if(f.tagName==="SELECT"){
    var opts=Array.from(f.options).map(function(o){return o.value+"="+o.textContent.trim()});
    return JSON.stringify({tag:"SELECT",opts:opts.slice(0,40)});
  }
  return JSON.stringify({tag:f.tagName,type:f.type,val:f.value});
})()
